@kt.kernel
def pick(x=kt.In(4, 32), y=kt.Out(4, 32), *, rows=kt.auto(4, 2, 1)):
    kt.require(rows != 1, "one row")
    for c in kt.par(1, on=kt.vc):
        kt.store(y[0:4, :], kt.load(x[0:4, :]))


def facts():
    g = {"x": TY.TensorSpec.make((4, 32))}

    def stale(t):
        raise ValueError("unknown field `acc_bits`")

    try:
        pick.trace(g, machine=MACHINE, check=stale)
    except kt.DSLError as e:
        lines = str(e).splitlines()
        return {"head": lines[0], "listed": len(lines) - 1}
    return {"head": None}
